"""Public setup metadata; contains no customer or platform credentials."""
COMMON=[{'name':'client_id','label':'Your broker account / client ID','secret':False}]
def field(name,label,secret=True):return {'name':name,'label':label,'secret':secret}
SETUP={
'dhan':dict(docs='https://dhanhq.co/docs/v2/authentication/',portal='https://web.dhan.co/',fields=[field('access_token','DhanHQ access token')],steps=['Open Dhan Web, My Profile, Access DhanHQ APIs.','Generate your own access token, then enter it here with your Dhan client ID.','GNK validates the token through Dhan profile; no orders are submitted.']),
'zerodha':dict(docs='https://kite.trade/docs/connect/v3/user/',portal='https://developers.kite.trade/',fields=[field('api_key','Kite API key',False),field('access_token','Kite access token')],steps=['Create your own Kite Connect application.','Complete Kite login and the official request-token exchange to obtain an access token.','Enter your own API key, access token and Zerodha user ID.']),
'upstox':dict(docs='https://upstox.com/developer/api-documentation/authentication/',portal='https://account.upstox.com/developer/apps',fields=[field('access_token','Upstox access token')],steps=['Create your own Upstox application and register its exact callback.','Complete official OAuth authorization to obtain your access token.','Enter your access token and Upstox user ID; GNK checks profile and active status.']),
'fyers':dict(docs='https://fyers.in/api-docs/v3/api/authentication/individual-app',portal='https://fyers.in/web/api-dashboard/user-apps',fields=[field('app_id','Your FYERS App ID',False),field('access_token','FYERS access token')],steps=['Create an individual application for your own FYERS account.','Complete FYERS authentication for your own App ID; non-trading apps can be used for account inspection.','Enter the App ID, access token and FYERS client ID.']),
'angelone':dict(docs='https://smartapi.angelone.in/docs',portal='https://smartapi.angelone.in/',fields=[field('api_key','SmartAPI API key',False),field('jwt_token','SmartAPI JWT access token')],steps=['Create your own SmartAPI application and authenticate on the official broker flow.','Copy the resulting JWT access token, not your broker password/PIN/OTP.','The GNK server operator must configure its actual BROKER_EGRESS_IP before profile validation.']),
'5paisa':dict(docs='https://xstream.5paisa.com/dev-docs/user-authentication-system/access-token',portal='https://xstream.5paisa.com/',fields=[field('app_key','Your 5paisa AppKey',False),field('user_id','API UserId',False),field('encryption_key','Your API encryption key'),field('request_token','Fresh OAuth RequestToken')],steps=['Obtain your own 5paisa API AppKey, UserId and encryption key.','Complete the official OAuth login to obtain a fresh one-time RequestToken.','GNK exchanges that token server-side and verifies the returned ClientCode.']),
'icici':dict(docs='https://api.icicidirect.com/breezeapi/documents/index.html',portal='https://api.icicidirect.com/apiuser/home',fields=[field('app_key','Your Breeze AppKey',False),field('api_session','Breeze API_Session from official login')],steps=['Register your individual Breeze application and authenticate at ICICI Direct.','Obtain API_Session from the official login flow.','GNK calls CustomerDetails and verifies the returned idirect_userid. A one-hour local connection deadline is used.'])}
LABELS={'dhan':'Dhan client ID','zerodha':'Zerodha user ID','upstox':'Upstox user ID','angelone':'Angel One client code','fyers':'FYERS client ID','5paisa':'5paisa ClientCode','icici':'Breeze idirect_userid (broker login user ID)'}
for broker,value in SETUP.items():value['fields']=[{'name':'client_id','label':LABELS[broker],'secret':False},*value['fields']]
